<?php
require __DIR__.'/config.php';$q=trim($_GET['q']??'');$results=[];
if(mb_strlen($q)>=2){$needle=mb_strtolower($q,'UTF-8');foreach(glob(DATA_DIR.'/*.json')?:[] as $f){$i=json_decode((string)file_get_contents($f),true)?:[];if(empty($i['published']))continue;foreach($i['articles']??[] as $a){$hay=mb_strtolower(($a['title']??'').' '.($a['text']??''),'UTF-8');if(mb_strpos($hay,$needle)!==false)$results[]=['issue'=>$i,'article'=>$a];}}}
?><!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="https://www.skutec.cz/favicon.ico"><title>Vyhledávání · Skutečské noviny</title><link rel="stylesheet" href="<?=BASE_PATH?>/assets/style.css?v=20260715-final2"></head><body><header class="top"><div class="topin"><a href="<?=BASE_PATH?>/">SKUTEČSKÉ NOVINY</a><span>Vyhledávání</span></div></header><main class="wrap hero"><h1>Hledat v novinách</h1><form class="searchform"><input name="q" value="<?=htmlspecialchars($q)?>" placeholder="Např. koupaliště, radnice, Skutíčko…" autofocus><button class="primary">Hledat</button></form><?php if($q):?><h2><?=count($results)?> výsledků pro „<?=htmlspecialchars($q)?>“</h2><div class="grid articles"><?php foreach($results as $r):$a=$r['article'];$i=$r['issue'];?><a class="card" href="<?=BASE_PATH?>/article.php?issue=<?=urlencode($i['id'])?>&amp;slug=<?=urlencode($a['slug']??slugify($a['title']))?>"><i class="cat cat-<?=htmlspecialchars($a['category']??'ostatni')?>"><?=htmlspecialchars($a['categoryLabel']??'Ostatní')?></i><h2><?=htmlspecialchars($a['title'])?></h2><p><?=sprintf('%02d/%d',$i['month'],$i['year'])?> · <?=htmlspecialchars(mb_substr($a['text']??'',0,220))?>…</p></a><?php endforeach;?></div><?php endif;?></main></body></html>